css:
.print-format-container {
    font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
    color: #333;
    padding: 10px;
}
.header-section h2 {
    margin-top: 0;
    color: #1f2937;
}
.section-title h3 {
    border-bottom: 2px solid #3b82f6;
    padding-bottom: 5px;
    color: #2563eb;
    margin-top: 25px;
}
.custom-table th {
    background-color: #f3f4f6 !important;
    color: #1f2937 !important;
    font-weight: bold;
    text-transform: uppercase;
    font-size: 11px;
}
.main-item-row {
    background-color: #ffffff;
}
.sub-item-row {
    background-color: #fafafa;
    font-style: italic;
}
.indent-arrow {
    color: #9ca3af;
    margin-right: 5px;
    font-weight: bold;
}
.text-right {
    text-align: right;
}
.text-center {
    text-align: center;
}

@media print {
    .custom-table th {
        background-color: #f3f4f6 !important;
        -webkit-print-color-adjust: exact;
    }
}
